#ifndef CC_SURFACES_DEBUG_VIEW_SINGLE
  #define CC_SURFACES_DEBUG_VIEW_SINGLE 1
#endif
#ifndef CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC
  #define CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC 2
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 v_uv;
vec4 vert () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1.0);
  v_uv = a_texCoord;
  #if SAMPLE_FROM_RT
    v_uv = cc_cameraPos.w > 1.0 ? vec2(v_uv.x, 1.0 - v_uv.y) : v_uv;
  #endif
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision mediump float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
in vec4 v_color;
in vec2 v_uv;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform BlurParams {
  vec4 blurParams;
};
vec4 frag () {
  vec2 texelSize = vec2(1.0) / max(blurParams.xy, vec2(1.0));
  float radius = blurParams.z;
  vec4 color = vec4(0.0);
  for (int i = -3; i <= 3; i++) {
    for (int j = -3; j <= 3; j++) {
      vec2 offset = vec2(float(i), float(j)) * texelSize * radius;
      vec4 tap = CCSampleWithAlphaSeparated(cc_spriteTexture, v_uv + offset);
      float wi = 0.0;
      float wj = 0.0;
      if (i == -3 || i == 3) wi = 0.0205;
      else if (i == -2 || i == 2) wi = 0.0855;
      else if (i == -1 || i == 1) wi = 0.232;
      else wi = 0.324;
      if (j == -3 || j == 3) wj = 0.0205;
      else if (j == -2 || j == 2) wj = 0.0855;
      else if (j == -1 || j == 1) wj = 0.232;
      else wj = 0.324;
      color += tap * (wi * wj);
    }
  }
  vec4 outColor = color * v_color;
  outColor.a = 1.0;
  return outColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

